// Aggregate weekly activity from GitHub API responses
const commits = $input.all()[0].json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;
const repo = $env.GITHUB_REPO || 'unknown/repo';

// Filter last 7 days
const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

const recentCommits = Array.isArray(commits) ? commits.filter(c => new Date(c.commit.author.date) > weekAgo) : [];
const recentIssues = Array.isArray(issues) ? issues.filter(i => new Date(i.closed_at) > weekAgo) : [];
const mergedPRs = Array.isArray(prs) ? prs.filter(p => p.merged_at && new Date(p.merged_at) > weekAgo) : [];

// Contributors
const authors = new Set();
recentCommits.forEach(c => {
  const name = c.commit?.author?.name || c.author?.login || 'unknown';
  authors.add(name);
});

// Build summary context for Claude
const context = {
  repo: repo,
  period: `${weekAgo.toISOString().split('T')[0]} to ${new Date().toISOString().split('T')[0]}`,
  stats: {
    commits: recentCommits.length,
    issues_closed: recentIssues.length,
    prs_merged: mergedPRs.length,
    contributors: authors.size
  },
  top_commits: recentCommits.slice(0, 5).map(c => ({
    message: c.commit.message.split('\n')[0].substring(0, 80),
    author: c.commit.author.name
  })),
  closed_issues: recentIssues.slice(0, 10).map(i => ({
    title: i.title,
    number: i.number
  })),
  merged_prs: mergedPRs.slice(0, 5).map(p => ({
    title: p.title,
    number: p.number
  }))
};

// Build prompt
const prompt = `You are a technical writer. Write a weekly dev summary for the ${repo} repository.

Activity this week (${context.period}):
- ${context.stats.commits} commits by ${context.stats.contributors} contributors
- ${context.stats.issues_closed} issues closed
- ${context.stats.prs_merged} PRs merged

Top commits:
${context.top_commits.map(c => `- ${c.message} (${c.author})`).join('\n')}

Closed issues:
${context.closed_issues.map(i => `- #${i.number}: ${i.title}`).join('\n')}

Merged PRs:
${context.merged_prs.map(p => `- #${p.number}: ${p.title}`).join('\n')}

Write a narrative summary (200-400 words) in ${$env.LANGUAGE || 'EN'}:
- Start with overall velocity (commits, contributors, PRs merged)
- Highlight the most impactful change
- Mention any notable bug fixes or new features
- End with a positive, forward-looking note
- Use emoji sparingly for visual appeal`;

return [{ json: { prompt, context } }];

const response = $input.first().json;
const text = response.content?.[0]?.text || 'Summary unavailable.';

const summary = `# 📊 Weekly Dev Summary — ${$env.GITHUB_REPO || 'Repo'}

${text}

---
*Auto-generated by n8n + Claude API • ${new Date().toISOString().split('T')[0]}*`;

return [{ json: { summary, raw_text: text } }];
